-- GENERATED by `wfj generate` from data/gossip/gossip-87.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["87100e3913332394"] = { "Fai attenzione là fuori nel deserto, {class}.", "." },
  ["8712b063ca13df97"] = { "La torre dei maghi a nord.", "." },
  ["87133471d840503b"] = { "Ora possediamo la saggezza degli Asciafredda, {name}. Questo potere può essere tuo per breve tempo, se lo desideri.", "." },
  ["871611293437a63a"] = { "Addio, mondo crudele... oggi ti lascio... addio... addio... addio...", "." },
  ["87172e2901ae62cc"] = { "Famosi in tutte le terre, gli articoli di Antonio Perelli ora in vendita vicino a ⟦Sentinel Hill=Guardiacolle⟧! Devo ripartire presto, quindi sbrigati.", "." },
  ["87198e66c9c15468"] = { "Fai sapere al maresciallo Windsor che sono <pronto/pronta>.", "." },
  ["8719c34dda9d6a13"] = { "<Lydros infila una mano nella veste e ti porge una lama elfica piatta e opaca.>\n\nNelle ere passate, ben prima ancora della Guerra degli Antichi, esisteva questa lama.", "." },
  ["871d6708ff79d390"] = { "Soldati dei Lupi Bianchi, venite in mio aiuto! È giunto il momento di scatenare su di loro la furia degli elementi!", "." },
  ["871fddcd54c4604b"] = { "Chi osa, da semplice {race}, immischiarsi in ciò che è passato? Possa la leggenda di Stalvan morire insieme a te!", "." },
  ["8721190046981167"] = { "Ci serve un gran numero di barre di rame, {class}. L'imminente guerra ad ⟦Ahn'Qiraj=Ahn'qiraj⟧ consumerà un sacco di metallo per armi, armature e quant'altro. Mi dicono che la sola ⟦Horde=Orda⟧ deve raccogliere $1998w barre di rame. Al momento ne abbiamo $2018w.", "." },
  ["872b1bae73102d0a"] = { "Mi riempi d'orgoglio. Sei davvero <un/una> <allievo/allieva> <dotato/dotata>. Ora, per la tua ultima lezione...", "." },
  ["8731d19c17d7787e"] = { "La corsa partirà tra 1 minuto!", "." },
  ["8732d7cf3af8e98c"] = { "Hai raggiunto nuove vette nel tuo cammino verso la maestria. Vediamo se possiamo portarti ancora più in alto...", "." },
  ["8732e2a91a4fe3c6"] = { "C'è una grande tenda sul lato est del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Lì troverai ⟦Narm Skychaser=Narm Preda Cielo⟧ ad attenderti.", "." },
  ["873bbd121f923a1f"] = { "Posto sgradevole, questa «⟦Undercity=Sepulcra⟧». Per niente simile alla Lordaeron di un tempo. Quanto mi manca...\n\nSe vuoi andare a Stratholme, temo di non poterti aiutare al momento. Le torri vicino alla città in fiamme sono ancora contese, e per questo i miei poteri sono troppo deboli per aiutarti. Torna da me quando avrai vinto là.", "." },
  ["873d42d17f1de9dc"] = { "La Frostwolf Relief Hut è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ la conquisterà!", "." },
  ["873e53ad9401fbd7"] = { "<Ayessa Dawnsinger ti fissa con una furia a stento trattenuta.>\n\nO hai molto coraggio, o pochissimo cervello, per mettere piede così sfacciatamente nel nostro dominio dopo aver versato sangue Windshaper. Siamo lenti a perdonare, e non dimentichiamo mai.\n\nFaresti meglio ad andartene subito. Se non fossimo al centro di Zephras, saresti già <morto/morta>.", "." },
  ["8743c613911c68c0"] = { "Sì, nessun problema, {name}! Scusa... pensavo che avessi già finito.", "." },
  ["8743f489559e88f0"] = { "Non si può permettere a questo male di entrare nel nostro mondo! Venite, figli miei!", "." },
  ["87513fb57afc6821"] = { "Qualsiasi occasione per combattere contro l'⟦Horde=Orda⟧, soprattutto contro gli orchi, è un bel divertimento, se vuoi saperlo. Troverai battaglia in abbondanza nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧, eccome. Vai al Salone delle Armi e parla con Lylandris. Ti indicherà la strada.", "." },
  ["875ad23f73d5ce46"] = { "Orsi??", "." },
  ["8762d206bf1e83ec"] = { "Quando impareranno?", "." },
  ["8767bd028dcce4e0"] = { "Temo che non riusciremo mai a placarli...", "." },
  ["876a22d5942b22ac"] = { "È il grande edificio di ⟦Razor Hill=Tranciacolle⟧ che non è la caserma. Parla con il locandiere Grosk, dentro. Capito?", "." },
  ["877dfc5fba9e3824"] = { "State all'erta, muli pigri!", "." },
  ["87805ce1b3266c6c"] = { "Alzo il boccale e spero di liberarmi di quelli come te! Salute, furfante buono a nulla, {name}!", "." },
  ["87829f10ac48ecfa"] = { "Hai l'aria di un fabbro, tu. Fuliggine sotto le unghie, acciaio nelle ossa. Già, hai proprio il sangue del fabbro nelle vene. Il che vuol dire che sei <venuto/venuta> da me per imparare una cosa o due: be', <ragazzo/ragazza>, prendi un martello. Vediamo cosa posso insegnarti.", "." },
  ["87859dc7ab542729"] = { "È vero che ho abilità da insegnare a chi ne è degno. Sei tu?", "." },
  ["8788490a4d2d5c8e"] = { "Lascia che ti porga i miei saluti per ⟦Greatfather Winter=Babbo Inverno⟧, feccia...", "." },
  ["878be02303428baf"] = { "Se pensi che io combatta bene, dovresti vedere mio marito.", "." },
  ["878f2a70d4117deb"] = { "Mi sarebbe bastato versare un po' di Evershine nel serbatoio e tornare a casa prima che si accorgessero della mia assenza!", "." },
  ["878fb61f93b25193"] = { "Puoi trovare Radnaal che pratica il suo mestiere fuori da casa sua, sulla strada per Darnassus. Dovresti passare a vedere cosa può insegnarti.", "." },
  ["879982941286b0cc"] = { "È terribile.", "." },
  ["879ba8cecc642812"] = { "Salute, che vuoi?", "." },
  ["879dbfe011ac6a66"] = { "A meno che?", "." },
  ["879e2af2512d6fee"] = { "Chi avrebbe mai detto che lo scavo avrebbe portato alla luce simili scoperte!", "." },
  ["87a36aabe529dcf1"] = { "Vuoi giocare? Allora giochiamo!", "." },
  ["87a73864de8a56fd"] = { "Le fanguzzole sono una razza di pesci particolarmente puzzolenti che ama le acque tropicali. La ⟦Zulian Mudskunk=Fanguzzola Zuliana⟧, la più puzzolente di tutte, si trova solo nelle acque afose di ⟦Zul'Gurub=Zul'gurub⟧.\n\nCredo che siano le Fanguzzole Zuliane ad aver attirato Gahz'ranka in quel luogo, anche se i troll probabilmente ti diranno che è uno dei loro dei...\n\nCredi a ciò che vuoi, ma ascoltami bene: riempi una delle mie esche di Fanguzzole Zuliane e quel vecchio arriverà di sicuro!", "." },
  ["87aad64f9aadfc7e"] = { "Intrusi! Uccideteli! Non lasciateli entrare nella stanza!", "." },
  ["87ab59c189c6a588"] = { "Come desideri, {class}.", "." },
  ["87ac366ca6bdebac"] = { "È una bella giornata per vivere, no? Lavoro duro e buon cibo: ci sono cose peggiori che potremmo fare in una giornata così bella.", "." },
  ["87aec11f91f3abba"] = { "Dov'è l'anziana Lanciachiara?", "." },
  ["87baf82cc0ae7514"] = { "Vengo da ⟦Ironforge=Forgiardente⟧ per dare una mano con la ricostruzione qui. Se riesco a insegnare le mie abilità a un bel po' di voi, forse potrò lasciare il lavoro a voi e tornarmene a casa.", "." },
  ["87bbc0c2d6576088"] = { "Pensi di avere abbastanza cervello? Pensi di avere quello che serve? Scopriamolo!", "." },
  ["87bfee5c3f6f80db"] = { "Guarda questi campioni! Che cosa significa? Che cosa significa? Mi servirà tempo, tempo per esaminare tutte queste informazioni. E mi serviranno altre informazioni. Informazioni che non posso ottenere... dannazione! Pensa, Laris, pensa!\n\nChe cosa farai? Cosa?!\n\nDeve esserci una soluzione!", "." },
  ["87c249787898ccff"] = { "Aiuto! Ho una mano sola per difendermi.", "." },
  ["87c3a21341a8a7f1"] = { "La mia veglia è eterna, mortale.", "." },
  ["87cb4a1a4e054519"] = { "Dovrei trovarmi un aiutante: non mi piace passare la giornata qui a vendere articoli da pesca. Preferirei di gran lunga andare a pescare, e poi vendere gli articoli.", "." },
  ["87d575f53a0864ba"] = { "Ora che il cristallo è qui...", "." },
  ["87dc1007c8dfcbe6"] = { "Da queste parti la maggior parte della gente non vede di buon occhio lo scasso. Come piccola cortesia professionale, lascia che ti mostri qualche trucco che ho imparato.", "." },
  ["87e1d7667c3e68d8"] = { "Realizzati dai migliori artigiani di tutta Teldrassil, portati a mano da Kalimdor ad Azeroth come segno della crescente alleanza tra il popolo del Grande Albero e gli umani di questa terra. Se ti serve qualcosa, non hai che da chiedere.", "." },
  ["87ea4acd97b1432f"] = { "%s in armamento. T meno 60 secondi.", "." },
  ["87ed0be4b4a72a69"] = { "La mia gamba va molto meglio, ora: il rimedio deve funzionare. Se vuoi scusarmi, devo andare a riferire ai miei superiori ciò che è successo qui.", "." },
  ["87f1e300230ca82e"] = { "Le bandiere sono ora collocate nelle loro basi.", "." },
  ["87f224005de77bc2"] = { "Solo un assaggino...", "." },
  ["87f6de6ee15558ec"] = { "%s spreme l'ultimo briciolo di vita da {name} e ne divora l'anima.", "." },
  ["87f778e40ef703b6"] = { "Servirò il padrone... nella morte!", "." },
  ["87fa8adffe3cf087"] = { "State in guardia!", "." },
  ["87fb5c4a958b4a98"] = { "⟦Glacial Wrists=Polsiere Glaciali⟧.", "." },
  ["87fe03a386b5e8e2"] = { "Mio signore. Da parte di padre Niflheim.", "." },
})
